 return new Response(request.method === 'HEAD' ? null : assets[path],{headers:{'Content-Type':type+'; charset=utf-8','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','Cache-Control':'no-cache','Cross-Origin-Opener-Policy':'same-origin-allow-popups'}});
